import styled from '@emotion/styled';

export const StyledFlaggedBrandCellRenderer = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
});

export const StyledFlaggedBrandCellRendererMainFlag = styled.div({
  fontSize: '14px',
});

export const StyledFlaggedBrandCellRendererDescription = styled.p({
  fontSize: '10px',
  color: '#5C5C5C',
});
